import json,pathlib,hashlib,collections,concurrent.futures,os,time,resource
BASE=pathlib.Path('/root/autodl-tmp/vsmt_outputs')
def audit(p):
    hashes={}
    def read(rel,default=None):
        f=p/rel
        if not f.exists(): return default
        b=f.read_bytes(); hashes[rel]=hashlib.sha256(b).hexdigest();return json.loads(b)
    rec=read('receipt.json',{})
    w=read('provenance/window_verdicts.json',{})
