    if rec.get('status')=='failed':r['dry_failed_rows']=pairs
    if w:
        subjects={k for k,x in w['subjects'].items() if x['sealed']}
        lo,hi=w['window']; seen=collections.defaultdict(set)
        for x in w['verdicts']:
            if x['unoccluded']>0: seen[x['container']].add(x['observation_index'])
        actual=subjects-set(seen)
        longest={}
        for c in subjects:
            best=cur=0
            for i in range(lo+1,hi+1):
                cur=0 if i in seen[c] else cur+1;best=max(best,cur)
            longest[c]=best
        by_frame=[len(subjects-{c for c in subjects if i in seen[c]}) for i in range(lo+1,hi+1)]
        r['window']={'frames':hi-lo,'containers':len(w['subjects']),'sealed':len(subjects),'U':len(w['invisible']),'U_matches_stored_verdicts':actual==set(w['invisible']),'U_ids':w['invisible'],'invisible_at_end':by_frame[-1] if by_frame else None,'invisible_per_frame_min':min(by_frame,default=None),'invisible_per_frame_max':max(by_frame,default=None),'containers_with_any_20_frame_invisible_streak':sum(n>=20 for n in longest.values()),'max_invisible_streak':max(longest.values(),default=0),'unsealed':{k:x for k,x in w['subjects'].items() if not x['sealed']}}
    return r
roots=[BASE/('lean-s1-02'+s+'-'+version) for version in ['7c10d2c','c222c51-superseded-by-ruling-50'] for s in ['a','b']]
tasks=sorted(p for root in roots for p in root.iterdir() if p.is_dir() and (p/'receipt.json').exists())
quota,period=map(int,pathlib.Path('/sys/fs/cgroup/cpu.max').read_text().split())
