workers=min(len(tasks),len(os.sched_getaffinity(0)),max(1,quota//period),max(1,available//(128*1024**2)))
start=time.time()
with concurrent.futures.ProcessPoolExecutor(max_workers=workers) as pool: rows=list(pool.map(audit,tasks))
out={'schema_version':'vsmt-s1-02-readonly-feasibility-audit-v1','scope':'stored receipt/provenance only; no simulator, no alternative-window selection, no dataset changes','resources':{'requested_workers':workers,'actual_workers':workers,'cpu_quota_cores':quota/period,'affinity_cores':len(os.sched_getaffinity(0)),'memory_available_bytes':available,'measured_largest_new_verdict_bytes':6257053,'measured_single_worker_peak_rss_kib':29956,'reserved_bytes_per_worker':128*1024**2,'bound':'CPU quota; small JSON reads only; one house per task','deterministic_merge':'lexicographic absolute episode path'},'tasks':len(tasks),'rows':rows,'seconds':time.time()-start,'exit_status':0}
